$ErrorActionPreference = 'Stop'
# Extract the approved fix script from the compressed payload below.
$encoded = @'

'@

$bytes = [Convert]::FromBase64String(($encoded -replace '\s', ''))
$memory = New-Object System.IO.MemoryStream
$memory.Write($bytes, 0, $bytes.Length)
$memory.Position = 0
$gzip = New-Object System.IO.Compression.GzipStream(
    $memory,
    [System.IO.Compression.CompressionMode]::Decompress
)
$reader = New-Object System.IO.StreamReader($gzip, [System.Text.Encoding]::UTF8)
$scriptBody = $reader.ReadToEnd()
$reader.Dispose()
$gzip.Dispose()
$memory.Dispose()

$tempScript = Join-Path $env:TEMP 'apply_imagekit_product_delete_fix_v2.ps1'
[System.IO.File]::WriteAllText(
    $tempScript,
    $scriptBody,
    (New-Object System.Text.UTF8Encoding($true))
)

& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $tempScript
if ($LASTEXITCODE -ne 0) {
    exit $LASTEXITCODE
}